fn frame(t: i32) {
    host::display::clear(0x000000);
    let w: i32 = host::display::width();
    let cy: i32 = host::display::height() / 2;
    let cx: i32 = w / 2;
    let amp: i32 = w / 2 - 40;
    let ex: i32 = cx + (amp * host::math::sin(t)) / 256;
    host::display::fill_rect(ex - 12, cy - 12, 24, 24, 0x33ddff);
    let ph: i32 = t % 512;
    let lin: i32 = if ph < 256 { ph } else { 512 - ph };
    let gx: i32 = cx - amp + (amp * 2 * lin) / 256;
    host::display::fill_rect(gx - 12, cy - 92, 24, 24, 0x444444);
    host::display::draw_string(20, cy - 120, "linear", 0x666666, 2);
    host::display::draw_string(20, cy + 40, "sine ease", 0x33ddff, 2);
    host::display::present();
}
